import {editorMarkup,mountEditor} from './editor.js';
import {migrateTree,layoutTree,addEnd} from './graph-model.js';
import {AVATARS,AVATAR_IDS,avatarFor,avatarSvg,heartSvg} from './avatars.js';
const SESSION='cupid-session',LEGACY='cupid-lab-v1';
const store={get:k=>{try{return localStorage.getItem(k)}catch{return null}},set:(k,v)=>{try{v==null?localStorage.removeItem(k):localStorage.setItem(k,v)}catch{}}};
let token=store.get(SESSION)||'',me=null,tab='tree',authMode='login',data={},skipped=new Set(),saving=Promise.resolve(),openPath=null;
const app=document.querySelector('#app');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.style.display='none',3400)}
async function api(path,method='GET',body){const r=await fetch('/api/'+path,{method,headers:{Authorization:'Bearer '+token,...(body!==undefined?{'Content-Type':'application/json'}:{})},body:body===undefined?undefined:JSON.stringify(body)});const result=await r.json().catch(()=>({error:'Unexpected server response.'}));if(r.status===401&&!path.match(/^(login|register)$/)){signedOut();throw Error('Your session ended. Sign in again.');}if(!r.ok)throw Error(result.error);return result;}
function signedOut(){token='';me=null;data={};store.set(SESSION,null);render();}
const pages={tree:'My formula',profile:'Profile',paths:'Paths',questions:'Questions',review:'Review',simulate:'Matches'};
const icons={tree:'M4 4h6v5H4z M14 15h6v5h-6z M4 15h6v5H4z M7 9v3h10v3 M7 12v3',profile:'M12 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M4 21v-2a8 8 0 0 1 16 0v2',paths:'M3 12h4l3-6 4 12 3-6h4',questions:'M4 4h16v12H9l-5 4z M8 8h8 M8 12h5',review:'M4 13h4l2 3h4l2-3h4 M4 13l2-8h12l2 8v6H4z',simulate:'m8 4 12 8-12 8z'};
const pic=(u,size)=>avatarSvg(u.avatar,u.id,size);
function render(){
 if(!me){app.innerHTML=authPage();bindAuth();return;}
 app.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand">Formula:Love</div><nav class="nav">${Object.entries(pages).map(([id,label])=>`<button data-tab="${id}" class="${tab===id?'active':''}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[id]}"/></svg>${label}${id==='review'&&me.reviewCount?`<span class="count" aria-label="${me.reviewCount} waiting">${me.reviewCount}</span>`:''}</button>`).join('')}</nav><div class="sidefoot">Prototype · your rules stay private.</div></aside><main class="workspace"><header class="topbar"><div class="context">Formula:Love <span>/</span> <strong>${pages[tab]}</strong></div><div class="person-switch">${pic(me,26)}<span class="small">${esc(me.username)}</span><button class="ghost" data-action="logout">Sign out</button></div></header><div class="page">${{tree:treePage,profile:profilePage,paths:pathsPage,questions:questionsPage,review:reviewPage,simulate:matchesPage}[tab]()}</div></main></div>`;
 bind();if(tab==='tree')mountEditor(me.tree,tree=>{me.tree=tree;render();saveTree(tree);},toast);
}
function authPage(){const login=authMode==='login';return `<main class="auth"><div class="brand">Formula:Love</div><h1>${login?'Sign in':'Create your account'}</h1><p class="muted">Design your own matchmaking algorithm. Your rules stay private.</p><form id="auth-form" class="card"><label class="field"><span>Username</span><input name="username" autocomplete="username" required minlength="3" maxlength="32" pattern="[A-Za-z0-9_]+"><small class="hint">${login?'':'Public: 3–32 letters, digits or underscores.'}</small></label><label class="field"><span>Password</span><input name="password" type="password" minlength="10" maxlength="256" autocomplete="${login?'current-password':'new-password'}" required>${login?'':'<small class="hint">At least 10 characters.</small>'}</label><p id="auth-error" class="error" role="alert"></p><button class="primary">${login?'Sign in':'Create account'}</button></form><p class="small muted">${login?'New here?':'Already have an account?'} <a href="#" data-auth="${login?'register':'login'}">${login?'Create an account':'Sign in'}</a></p></main>`}
function bindAuth(){document.querySelector('[data-auth]').onclick=e=>{e.preventDefault();authMode=e.target.dataset.auth;render();};document.querySelector('#auth-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),button=e.target.querySelector('button');button.disabled=true;try{const session=await api(authMode,'POST',{username:f.get('username'),password:f.get('password')});token=session.token;store.set(SESSION,token);await loadMe();go('tree');}catch(err){document.querySelector('#auth-error').textContent=err.message;button.disabled=false;}};}
// Formulas laid out before the Start bubble existed are rearranged once (left to right, room for Start), then flagged.
function toLeftToRight(tree){if(tree.layout==='ltr2')return false;if(tree.nodes.length){addEnd(tree);layoutTree(tree);}tree.layout='ltr2';return true;}
async function loadMe(){me=await api('me');me.tree=migrateTree(me.tree);if(toLeftToRight(me.tree))saveTree(me.tree);}
// Saves run in order so a slow request never overwrites a newer tree.
function saveTree(tree){const body=JSON.parse(JSON.stringify(tree));saving=saving.then(()=>api('tree','PUT',body)).catch(e=>toast('Not saved: '+e.message));return saving;}
async function load(names){try{const results=await Promise.all(names.map(n=>api(n)));names.forEach((n,i)=>data[n]=results[i]);}catch(e){toast(e.message);}render();}
function go(next){tab=next;history.replaceState(null,'','#'+next);render();const needs={tree:['visitors'],paths:['paths'],questions:['questions','responses/sent'],review:['responses/inbox'],simulate:['matches']}[next];if(needs)load(needs);}
function title(name,desc,actions=''){return `<div class="pagehead"><div><h1>${name}</h1><p>${desc}</p></div><div class="actions">${actions}</div></div>`}
function legacyTree(){if(store.get('cupid-import-dismissed')||me.tree.nodes.length)return null;try{const tree=JSON.parse(store.get(LEGACY))?.profiles?.find(p=>p.id==='you')?.tree;return tree?.nodes?.length?tree:null;}catch{return null;}}
function treePage(){const legacy=legacyTree();return title('My formula','Your matchmaking algorithm: questions lead from Start to the heart.','<button data-action="export">Export formula</button><button class="primary" data-tab="simulate">View matches</button>')+(legacy?`<div class="notice">This browser has a formula from before accounts (${legacy.nodes.length} steps). <button data-action="import-legacy">Import it</button> <button class="ghost" data-action="dismiss-legacy">Dismiss</button></div>`:'')+visitorsCard()+editorMarkup(me.tree,me.id);}
function input(label,name,value,hint=''){return `<label class="field"><span>${label}</span><input name="${name}" value="${esc(value)}">${hint?`<small class="hint">${hint}</small>`:''}</label>`}
function profilePage(){const current=avatarFor(me.avatar,me.id);return `${title('Profile','Everyone sees your username and picture. The rest waits for a mutual match.')}<form id="profile-form"><div class="cards"><section class="card"><h2>Public profile</h2><p class="muted small">Shown to everyone, including on responses you send.</p><div class="profile-heading">${pic(me,52)}<div><strong>${esc(me.username)}</strong><div class="small muted">${esc(AVATARS[current].label)}</div></div></div><div class="field"><span>Picture</span><div class="avatar-grid" role="radiogroup" aria-label="Profile picture">${AVATAR_IDS.map(id=>`<label class="avatar-option"><input type="radio" name="avatar" value="${id}" ${id===current?'checked':''}>${avatarSvg(id,'',36)}<span>${esc(AVATARS[id].label)}</span></label>`).join('')}</div><small class="hint">Custom pictures are coming later.</small></div><hr class="sectionline"><h3>Revealed after a match</h3>${input('Name','name',me.name)}<label class="field"><span>About you</span><textarea name="bio" rows="4">${esc(me.bio)}</textarea></label><label class="field"><span>Public hobbies</span><textarea name="publicHobbies" rows="3">${esc(me.publicHobbies)}</textarea><small class="hint">Separate interests with commas.</small></label></section><section class="card"><span class="badge">Private</span><h2 style="margin-top:12px">Private context</h2><p class="muted small">Used for matching, never shown to anyone.</p><label class="field"><span>Private hobbies</span><textarea name="privateHobbies" rows="4">${esc(me.privateHobbies)}</textarea></label><div class="note-card"><h3>How hobby matching works</h3><p>A hobby condition compares both lists. A match can see that compatible interests exist, without seeing the hidden hobby names.</p></div><p class="privacy">Signed in with: ${me.identities.map(p=>p==='password'?'username and password':esc(p)).join(', ')}. Google, Discord and LinkedIn sign-in are planned.</p></section></div><div class="export-row"><button type="submit" class="primary">Save profile</button></div></form>`}
// Pixel heart at the end of every path: filled when reached, faded when the path ended.
const heart=heartSvg;
const pathStatus=e=>e.status==='match'?'Reached the heart':e.status==='reject'?'Path ended':e.status==='friends'?'Ended as friends':e.reviewing?'Waiting for their review':`${e.passed} of ${e.total} steps`;
// Steps already passed are filled, the rest stay blacked out; the marker sits on the current step.
function track(e,marker){const steps=Math.max(e.total,e.passed),done=e.status==='match',ended=['reject','friends'].includes(e.status),at=done?steps:e.passed;return `<div class="track${ended?' ended':''}" role="img" aria-label="${esc(pathStatus(e))}">${Array.from({length:steps},(_,i)=>`<span class="step ${i<e.passed?'passed':'hidden'}">${i===at?`<span class="marker">${pic(marker,22)}</span>`:''}</span>`).join('')}<span class="goal">${at===steps?`<span class="marker">${pic(marker,22)}</span>`:''}${heart(done?'reached':ended?'faded':'')}</span></div>`}
function pathsPage(){const list=data.paths;return title('Paths','Everyone’s path runs from start to the heart. Steps stay hidden until you reach them.')+`<section class="card">${!list?'<p class="muted">Loading…</p>':!list.length?'<p class="muted">No one else has a finished formula yet.</p>':`<ul class="paths">${list.map(e=>`<li><div class="path-head">${pic(e.owner,32)}<strong>@${esc(e.owner.username)}</strong><span class="small muted">${esc(pathStatus(e))}</span>${e.status==='pending'&&!e.reviewing?`<button data-path="${esc(e.owner.id)}" ${openPath===e.owner.id?'class="primary"':''}>${openPath===e.owner.id?'Close':'Continue'}</button>`:''}</div>${track(e,me)}${openPath===e.owner.id?pathQuestion():''}</li>`).join('')}</ul>`}</section>`}
function pathQuestion(){const list=data.pathQ;if(!list)return '<p class="muted small">Loading…</p>';const q=list[0];return q?`<div class="path-question" data-qtoken="${esc(q.token)}"><h3>${esc(q.label)}</h3>${questionControl(q)}</div>`:'<p class="muted small">Nothing to answer here right now.</p>'}
function visitorsCard(){const list=data.visitors;if(!list?.length)return '';return `<section class="card visitors"><div class="response-head"><h2>Visitors on your path</h2><span class="small muted">${list.length} ${list.length===1?'person':'people'}</span></div><ul class="paths">${list.map(v=>`<li><div class="path-head">${pic(v.visitor,24)}<strong>@${esc(v.visitor.username)}</strong><span class="small muted">${esc(pathStatus(v))}</span></div>${track(v,v.visitor)}</li>`).join('')}</ul></section>`}
function questionControl(q){if(q.type==='text')return `<form class="text-answer"><textarea class="text" name="value" rows="4" maxlength="1000" required placeholder="Write your response" aria-label="Your response"></textarea><div class="actions" style="margin-top:8px"><button class="primary">Send response</button><small class="hint">The person who asked sees your username and picture with it.</small></div></form>`;if(q.type==='scale')return `<form class="choices number-answer"><input class="text number-input" name="value" type="number" inputmode="decimal" required step="${q.integer?1:'any'}" ${q.min!=null?`min="${q.min}"`:''} ${q.max!=null?`max="${q.max}"`:''} aria-label="Your answer" placeholder="${q.min!=null&&q.max!=null?`${q.min}–${q.max}`:q.integer?'Whole number':'Number'}"><button class="primary">Answer</button></form>`;if(q.type==='boolean')return `<div class="choices"><button data-answer="true">Yes</button><button data-answer="false">No</button></div>`;if(q.type==='category')return `<div class="choices">${q.options.map((o,i)=>`<button data-option="${i}">${esc(o)}</button>`).join('')}</div>`;return ''}
function questionCard(){const list=data.questions;if(!list)return '<section class="card"><p class="muted">Loading…</p></section>';const q=list.find(q=>!skipped.has(q.token));return `<section class="card" style="max-width:650px" ${q?`data-qtoken="${esc(q.token)}"`:''}>${q?`<span class="eyebrow">From someone's formula</span><h2 style="margin-top:6px">${esc(q.label)}</h2>${questionControl(q)}<button class="ghost" data-skip="${esc(q.token)}">Skip for now</button>`:'<p class="muted">No questions right now. Check back after more people build their trees.</p>'}</section>`}
function questionsPage(){return title('Questions','Answer at your own pace. Skip anything you like.')+questionCard()+sentList();}
const statusBadge=s=>({pending:'<span class="badge amber">Waiting for review</span>',approved:'<span class="badge green">Approved</span>',rejected:'<span class="badge">Not approved</span>'})[s];
function sentList(){const list=data['responses/sent'];if(!list?.length)return '';return `<section class="card" style="max-width:650px;margin-top:16px"><h2>Your responses</h2><ul class="people responses">${list.map(r=>`<li>${pic(r.owner,32)}<div><div class="response-head"><strong>@${esc(r.owner.username)}</strong>${statusBadge(r.status)}</div><p class="small muted">${esc(r.prompt)}</p><blockquote>${esc(r.text)}</blockquote></div></li>`).join('')}</ul></section>`}
function reviewPage(){const list=data['responses/inbox'];return title('Review','Responses to your open-ended questions. Decide whenever you like.')+`<section class="card" style="max-width:720px">${!list?'<p class="muted">Loading…</p>':!list.length?'<p class="muted">Nothing to review. Responses to your open-ended questions appear here.</p>':`<ul class="people responses">${list.map(r=>`<li>${pic(r.from,32)}<div><div class="response-head"><strong>@${esc(r.from.username)}</strong><span class="small muted">${new Date(r.createdAt).toLocaleDateString()}</span></div><p class="small muted">${esc(r.prompt)}</p><blockquote>${esc(r.text)}</blockquote><div class="actions"><button class="primary" data-decide="${esc(r.id)}" data-approve="true">Approve</button><button data-decide="${esc(r.id)}" data-approve="false">Not approved</button><details class="more"><summary>More</summary><div class="actions"><button class="ghost danger" data-block="${esc(r.from.id)}">Block @${esc(r.from.username)}</button></div><form class="report-form" data-report="${esc(r.from.id)}"><textarea class="text" name="reason" rows="2" maxlength="1000" required placeholder="What is wrong with this response?" aria-label="Report reason"></textarea><button>Report</button></form></details></div></div></li>`).join('')}</ul>`}</section>`}
function matchesPage(){const m=data.matches;return title('Matches','You both reached the heart on each other’s paths.')+`<section class="card" style="margin-bottom:16px"><h2>Mutual matches</h2>${!m?'<p class="muted">Loading…</p>':!m.length?'<p class="muted">No mutual matches yet.</p>':`<ul class="people">${m.map(x=>`<li>${pic(x,32)}<div><strong>${esc(x.name)}</strong> <span class="small muted">@${esc(x.username)}</span>${x.bio?`<p class="small">${esc(x.bio)}</p>`:''}${x.publicHobbies?`<p class="small muted">${esc(x.publicHobbies)}</p>`:''}</div></li>`).join('')}</ul>`}</section>`;}
const findQ=token=>[...(data.questions||[]),...(data.pathQ||[])].find(q=>q.token===token);
async function openPathFor(owner){openPath=owner;data.pathQ=null;render();if(!owner)return;try{data.pathQ=await api('questions?owner='+encodeURIComponent(owner));}catch(e){toast(e.message);}render();}
async function answer(token,value){try{const r=await api('answers','POST',{token,value});if(r.pending)toast('Sent. It waits for their review.');if(tab==='paths'){await load(['paths']);if(openPath)await openPathFor(r.pending?null:openPath);}else await load(['questions','responses/sent']);}catch(e){toast(e.message);}}
async function refreshReview(message){try{data['responses/inbox']=await api('responses/inbox');me.reviewCount=data['responses/inbox'].length;render();if(message)toast(message);}catch(e){toast(e.message);}}
function bind(){
 document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>go(b.dataset.tab));
 document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));
 document.querySelectorAll('[data-skip]').forEach(b=>b.onclick=()=>{skipped.add(b.dataset.skip);render();});
 const tokenOf=el=>el.closest('[data-qtoken]').dataset.qtoken;
 document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>answer(tokenOf(b),b.dataset.answer==='true'));
 document.querySelectorAll('[data-option]').forEach(b=>b.onclick=()=>{const t=tokenOf(b);answer(t,findQ(t).options[b.dataset.option]);});
 document.querySelectorAll('.number-answer').forEach(f=>f.onsubmit=e=>{e.preventDefault();answer(tokenOf(f),Number(f.elements.value.value));});
 document.querySelectorAll('.text-answer').forEach(f=>f.onsubmit=e=>{e.preventDefault();answer(tokenOf(f),f.elements.value.value);});
 document.querySelectorAll('[data-path]').forEach(b=>b.onclick=()=>openPathFor(openPath===b.dataset.path?null:b.dataset.path));
 document.querySelectorAll('[data-decide]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await api('responses/decide','POST',{id:b.dataset.decide,approve:b.dataset.approve==='true'});await refreshReview(b.dataset.approve==='true'?'Approved.':'Marked not approved.');}catch(e){toast(e.message);b.disabled=false;}});
 document.querySelectorAll('[data-block]').forEach(b=>b.onclick=async()=>{try{await api('block','POST',{userId:b.dataset.block});await refreshReview('Blocked. You will not see each other again.');}catch(e){toast(e.message);}});
 document.querySelectorAll('[data-report]').forEach(f=>f.onsubmit=async e=>{e.preventDefault();try{await api('report','POST',{userId:f.dataset.report,reason:f.elements.reason.value});f.closest('details').open=false;toast('Report sent. Thank you.');}catch(err){toast(err.message);}});
 document.querySelector('#profile-form')?.addEventListener('change',e=>{if(e.target.name==='avatar'){me.avatar=e.target.value;render();}});
 document.querySelector('#profile-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));try{const tree=me.tree;me=await api('profile','PUT',f);me.tree=tree;render();toast('Profile saved.');}catch(err){toast(err.message);}});
}
async function action(a){
 if(a==='logout'){try{await api('logout','POST',{});}catch{}signedOut();}
 else if(a==='export'){const blob=new Blob([JSON.stringify(me.tree,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='my-formula.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
 else if(a==='dismiss-legacy'){store.set('cupid-import-dismissed','1');render();}
 else if(a==='import-legacy'){const tree=migrateTree(JSON.parse(JSON.stringify(legacyTree())));toLeftToRight(tree);try{await api('tree','PUT',tree);me.tree=tree;store.set('cupid-import-dismissed','1');render();toast('Formula imported to your account.');}catch(e){toast('Could not import: '+e.message);}}
}
const start=location.hash.slice(1);if(start in pages)tab=start;
if(token)loadMe().then(()=>go(tab),()=>{if(token)signedOut();});else render();
